import { expect, test } from "../../fixtures";

test.describe("Review vendors", () => {
  test("Members cannot see the review queue", { tag: "@REV-04" }, async ({ apiAs }) => {
    // Given I am signed in as member@northwind.test
    const member = await apiAs("member");

    // When I open the review queue
    const response = await member.get("/api/review-queue");
    const bodyText = await response.text();

    // Then the response status is 403
    expect(response.status(), bodyText).toBe(403);

    // And the error code is "forbidden"
    const body = JSON.parse(bodyText);
    expect(body?.error?.code, bodyText).toBe("forbidden");
  });
});
